{
  "name": "Inbox under control - AI draft",
  "nodes": [
    {
      "parameters": {
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        },
        "simple": false,
        "filters": {
          "labelIds": [
            "INBOX"
          ],
          "readStatus": "unread"
        },
        "options": {}
      },
      "id": "n8n-mail-01",
      "name": "New email",
      "type": "n8n-nodes-base.gmailTrigger",
      "typeVersion": 1.2,
      "position": [
        -260,
        0
      ]
    },
    {
      "parameters": {
        "modelId": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "messages": {
          "values": [
            {
              "role": "system",
              "content": "You are the assistant for [YOUR NAME], who runs [YOUR BUSINESS]. You write reply drafts in professional English, in under 120 words. Never invent prices, deadlines, or availability: if the email asks for something you don't have, leave the gap written as [CONFIRM]. Don't promise anything. Always sign as [YOUR NAME]. If the email is advertising, an automated invoice, or an app notification, reply with exactly the word IGNORE and nothing else."
            },
            {
              "content": "=From: {{ $json.from.value[0].address }}\nSubject: {{ $json.subject }}\n\n{{ $json.text }}"
            }
          ]
        },
        "options": {
          "temperature": 0.3
        }
      },
      "id": "n8n-mail-02",
      "name": "AI drafts",
      "type": "@n8n/n8n-nodes-langchain.openAi",
      "typeVersion": 1.8,
      "position": [
        -40,
        0
      ]
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": false,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-ignorar",
              "leftValue": "={{ $json.message.content }}",
              "rightValue": "IGNORE",
              "operator": {
                "type": "string",
                "operation": "notContains"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-mail-03",
      "name": "Deserves a reply",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        180,
        0
      ]
    },
    {
      "parameters": {
        "resource": "draft",
        "subject": "=Re: {{ $('New email').item.json.subject }}",
        "emailType": "text",
        "message": "={{ $json.message.content }}",
        "options": {
          "sendTo": "={{ $('New email').item.json.from.value[0].address }}",
          "threadId": "={{ $('New email').item.json.threadId }}"
        }
      },
      "id": "n8n-mail-04",
      "name": "Save draft",
      "type": "n8n-nodes-base.gmail",
      "typeVersion": 2.1,
      "position": [
        420,
        -100
      ]
    }
  ],
  "connections": {
    "New email": {
      "main": [
        [
          {
            "node": "AI drafts",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "AI drafts": {
      "main": [
        [
          {
            "node": "Deserves a reply",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Deserves a reply": {
      "main": [
        [
          {
            "node": "Save draft",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "WhatsApp Assistant",
  "nodes": [
    {
      "parameters": {
        "updates": [
          "messages"
        ]
      },
      "id": "n8n-wa-01",
      "name": "WhatsApp message",
      "type": "n8n-nodes-base.whatsAppTrigger",
      "typeVersion": 1,
      "position": [
        -260,
        0
      ],
      "webhookId": "change-me-on-import"
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": true,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-texto",
              "leftValue": "={{ $json.messages[0].type }}",
              "rightValue": "text",
              "operator": {
                "type": "string",
                "operation": "equals"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-wa-02",
      "name": "Text only",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        -40,
        0
      ]
    },
    {
      "parameters": {
        "modelId": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "messages": {
          "values": [
            {
              "role": "system",
              "content": "You are the WhatsApp assistant for [YOUR BUSINESS]. You reply in professional English, in 2 or 3 sentences at most, no lists or bold text: it's WhatsApp, not an email. Data you can give: hours [YOUR HOURS], address [YOUR ADDRESS], approximate prices [YOUR PRICES]. If asked something not on that list, say a person will look into it and reply within [YOUR TIMEFRAME]. Never confirm a booking or charge anything."
            },
            {
              "content": "={{ $json.messages[0].text.body }}"
            }
          ]
        },
        "options": {
          "temperature": 0.4
        }
      },
      "id": "n8n-wa-03",
      "name": "AI replies",
      "type": "@n8n/n8n-nodes-langchain.openAi",
      "typeVersion": 1.8,
      "position": [
        180,
        -100
      ]
    },
    {
      "parameters": {
        "operation": "send",
        "phoneNumberId": "PASTE_HERE_YOUR_PHONE_NUMBER_ID",
        "recipientPhoneNumber": "={{ $('WhatsApp message').item.json.messages[0].from }}",
        "textBody": "={{ $json.message.content }}",
        "additionalFields": {}
      },
      "id": "n8n-wa-04",
      "name": "Reply via WhatsApp",
      "type": "n8n-nodes-base.whatsApp",
      "typeVersion": 1,
      "position": [
        400,
        -100
      ]
    }
  ],
  "connections": {
    "WhatsApp message": {
      "main": [
        [
          {
            "node": "Text only",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Text only": {
      "main": [
        [
          {
            "node": "AI replies",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    },
    "AI replies": {
      "main": [
        [
          {
            "node": "Reply via WhatsApp",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "My Website Watchdog",
  "nodes": [
    {
      "parameters": {
        "rule": {
          "interval": [
            {
              "field": "minutes",
              "minutesInterval": 15
            }
          ]
        }
      },
      "id": "n8n-vig-01",
      "name": "Every 15 minutes",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1.2,
      "position": [
        -280,
        0
      ]
    },
    {
      "parameters": {
        "url": "https://[YOUR-DOMAIN].com",
        "options": {
          "timeout": 10000,
          "response": {
            "response": {
              "fullResponse": true,
              "neverError": true
            }
          }
        }
      },
      "id": "n8n-vig-02",
      "name": "Call the website",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        -60,
        0
      ]
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": true,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-caida",
              "leftValue": "={{ $json.statusCode }}",
              "rightValue": 200,
              "operator": {
                "type": "number",
                "operation": "notEquals"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-vig-03",
      "name": "Is down",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        160,
        0
      ]
    },
    {
      "parameters": {
        "chatId": "PASTE_HERE_YOUR_CHAT_ID",
        "text": "=🔴 [YOUR-DOMAIN].com is not responding properly.\nCode: {{ $json.statusCode }}\nTime: {{ $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm') }}",
        "additionalFields": {}
      },
      "id": "n8n-vig-04",
      "name": "Notify me via Telegram",
      "type": "n8n-nodes-base.telegram",
      "typeVersion": 1.2,
      "position": [
        400,
        -100
      ]
    }
  ],
  "connections": {
    "Every 15 minutes": {
      "main": [
        [
          {
            "node": "Call the website",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Call the website": {
      "main": [
        [
          {
            "node": "Is down",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Is down": {
      "main": [
        [
          {
            "node": "Notify me via Telegram",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "Notify me when something breaks",
  "nodes": [
    {
      "parameters": {},
      "id": "n8n-err-01",
      "name": "When a flow fails",
      "type": "n8n-nodes-base.errorTrigger",
      "typeVersion": 1,
      "position": [
        -200,
        0
      ]
    },
    {
      "parameters": {
        "chatId": "PASTE_HERE_YOUR_CHAT_ID",
        "text": "=⚠️ An n8n flow just broke\n\nFlow: {{ $json.workflow.name }}\nNode: {{ $json.execution.lastNodeExecuted }}\nError: {{ $json.execution.error.message }}\n\nView it: {{ $json.execution.url }}",
        "additionalFields": {}
      },
      "id": "n8n-err-02",
      "name": "Notify me via Telegram",
      "type": "n8n-nodes-base.telegram",
      "typeVersion": 1.2,
      "position": [
        40,
        0
      ]
    }
  ],
  "connections": {
    "When a flow fails": {
      "main": [
        [
          {
            "node": "Notify me via Telegram",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}
